BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "CATEGORIES" (
	"Category_id"	INTEGER,
	"Category_name"	TEXT NOT NULL UNIQUE,
	"Display_order"	INTEGER DEFAULT 0,
	"Is_active"	INTEGER DEFAULT 1 CHECK("Is_active" IN (0, 1)),
	"Created_at"	TEXT DEFAULT (datetime('now', 'localtime')),
	PRIMARY KEY("Category_id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "DELIVERY_PLATFORMS" (
	"Platform_id"	INTEGER,
	"Platform_name"	TEXT NOT NULL,
	"Platform_code"	TEXT NOT NULL UNIQUE,
	"Fee_percentage"	REAL DEFAULT 0,
	"Icon_class"	TEXT DEFAULT 'fa-solid fa-motorcycle',
	"Color_code"	TEXT DEFAULT '#ff5722',
	"Is_active"	INTEGER DEFAULT 1,
	"Sort_order"	INTEGER DEFAULT 0,
	"Created_at"	DATETIME DEFAULT (datetime('now', 'localtime')),
	PRIMARY KEY("Platform_id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "DINING_TABLES" (
	"Table_id"	INTEGER,
	"Table_code"	TEXT NOT NULL UNIQUE,
	"Table_name"	TEXT NOT NULL,
	"Area"	TEXT DEFAULT 'Tầng 1',
	"Capacity"	INTEGER DEFAULT 4,
	"Current_guests"	INTEGER DEFAULT 0,
	"Status"	TEXT DEFAULT 'EMPTY',
	"Current_order_id"	INTEGER,
	"Current_order_code"	TEXT,
	"Current_amount"	REAL DEFAULT 0,
	"Payment_status"	TEXT DEFAULT 'UNPAID',
	"Note"	TEXT,
	"Sort_order"	INTEGER DEFAULT 0,
	"Created_at"	DATETIME DEFAULT (datetime('now', 'localtime')),
	"Updated_at"	DATETIME DEFAULT (datetime('now', 'localtime')),
	PRIMARY KEY("Table_id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "GUEST_LOGS" (
	"Log_id"	INTEGER,
	"Table_id"	INTEGER,
	"Table_name"	TEXT,
	"Order_id"	INTEGER,
	"Order_code"	TEXT,
	"Guest_count"	INTEGER DEFAULT 1,
	"Action_type"	TEXT,
	"Staff_username"	TEXT,
	"Note"	TEXT,
	"Created_at"	DATETIME DEFAULT (datetime('now', 'localtime')),
	PRIMARY KEY("Log_id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "MENU_ITEMS" (
	"Item_id"	INTEGER,
	"Category_id"	INTEGER NOT NULL,
	"Item_code"	TEXT NOT NULL UNIQUE,
	"Item_name"	TEXT NOT NULL,
	"Base_price"	INTEGER NOT NULL,
	"Cost_price"	INTEGER DEFAULT 0,
	"Image_url"	TEXT,
	"Description"	TEXT,
	"Is_available"	INTEGER DEFAULT 1 CHECK("Is_available" IN (0, 1)),
	"Printer_target"	TEXT DEFAULT 'KITCHEN_MAIN',
	"Created_at"	TEXT DEFAULT (datetime('now', 'localtime')),
	"Toppings"	TEXT,
	PRIMARY KEY("Item_id" AUTOINCREMENT),
	FOREIGN KEY("Category_id") REFERENCES "CATEGORIES"("Category_id") ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS "ORDERS" (
	"Order_id"	INTEGER,
	"Order_code"	TEXT NOT NULL UNIQUE,
	"Order_type"	TEXT DEFAULT 'DINE_IN',
	"Table_number"	TEXT,
	"Customer_name"	TEXT,
	"Payment_method"	TEXT DEFAULT 'CASH',
	"Final_amount"	REAL DEFAULT 0,
	"Note"	TEXT,
	"Created_at"	DATETIME DEFAULT (datetime('now', 'localtime')),
	"Status"	TEXT DEFAULT 'PENDING',
	"Table_id"	TEXT DEFAULT '',
	"Table_name"	TEXT DEFAULT '',
	"Total_amount"	REAL DEFAULT 0,
	"Cancel_role"	TEXT,
	"Cancel_reason"	TEXT,
	"Is_edited"	INTEGER DEFAULT 0,
	"Payment_status"	TEXT DEFAULT 'UNPAID',
	"Paid_by"	TEXT,
	"Paid_at"	DATETIME,
	"Staff_name"	TEXT,
	"Created_by"	TEXT,
	"Guest_count"	INTEGER DEFAULT 1,
	"Delivery_platform"	TEXT DEFAULT '',
	"Customer_phone"	TEXT DEFAULT '',
	"Delivery_address"	TEXT DEFAULT '',
	"Shipping_fee"	REAL DEFAULT 0,
	"Payment_type"	TEXT DEFAULT 'COD',
	"Shipping_status"	TEXT DEFAULT 'PENDING',
	PRIMARY KEY("Order_id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "ORDER_DETAILS" (
	"Detail_id"	INTEGER,
	"Order_id"	INTEGER NOT NULL,
	"Item_name"	TEXT NOT NULL,
	"Quantity"	INTEGER NOT NULL DEFAULT 1,
	"Unit_price"	REAL NOT NULL DEFAULT 0,
	"Total_price"	REAL NOT NULL DEFAULT 0,
	"Note"	TEXT,
	"Toppings"	TEXT,
	PRIMARY KEY("Detail_id" AUTOINCREMENT),
	FOREIGN KEY("Order_id") REFERENCES "ORDERS"("Order_id") ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS "ORDER_LOGS" (
	"Log_id"	INTEGER,
	"Order_code"	TEXT NOT NULL,
	"Modified_by"	TEXT DEFAULT 'Hệ thống',
	"Old_content"	TEXT,
	"New_content"	TEXT,
	"Modified_at"	DATETIME DEFAULT (datetime('now', 'localtime')),
	PRIMARY KEY("Log_id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "PAYMENT_METHODS" (
	"Payment_id"	INTEGER,
	"Payment_code"	TEXT NOT NULL UNIQUE,
	"Payment_name"	TEXT NOT NULL,
	"Guide_info"	TEXT,
	"Is_active"	INTEGER DEFAULT 1,
	PRIMARY KEY("Payment_id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "PROMOTION_BANNERS" (
	"Banner_id"	INTEGER,
	"Title"	TEXT NOT NULL,
	"Subtitle"	TEXT,
	"Badge_text"	TEXT DEFAULT 'MỚI',
	"Price_text"	TEXT,
	"Image_url"	TEXT NOT NULL,
	"Sort_order"	INTEGER DEFAULT 0,
	"Is_active"	INTEGER DEFAULT 1,
	"Created_at"	DATETIME DEFAULT (datetime('now', 'localtime')),
	PRIMARY KEY("Banner_id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "STAFF_KPI_LOGS" (
	"Log_id"	INTEGER,
	"Staff_username"	TEXT NOT NULL,
	"Staff_name"	TEXT,
	"Staff_role"	TEXT,
	"Action_type"	TEXT NOT NULL,
	"Order_id"	INTEGER,
	"Order_code"	TEXT,
	"Table_number"	TEXT,
	"Amount"	REAL DEFAULT 0,
	"Item_count"	INTEGER DEFAULT 0,
	"Note"	TEXT,
	"Created_at"	DATETIME DEFAULT (datetime('now', 'localtime')),
	PRIMARY KEY("Log_id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "SYSTEM_CONFIG" (
	"Key"	TEXT,
	"Value"	TEXT,
	"Updated_at"	DATETIME DEFAULT (datetime('now', 'localtime')),
	PRIMARY KEY("Key")
);
CREATE TABLE IF NOT EXISTS "USERS" (
	"User_id"	INTEGER,
	"User_name"	TEXT NOT NULL UNIQUE,
	"User_password"	TEXT NOT NULL,
	"Role"	TEXT DEFAULT 'WAITER' CHECK("Role" IN ('ADMIN', 'CASHIER', 'KITCHEN', 'WAITER', 'CUSTOMER')),
	"Created_at"	DATETIME DEFAULT (DATETIME('now', 'localtime')),
	PRIMARY KEY("User_id" AUTOINCREMENT)
);
COMMIT;
